+package org.apache.streampipes.client.util;
+
+import java.net.URI;
+import java.net.URISyntaxException;
+
+public final class InstallEndpointValidator {
+
+  private InstallEndpointValidator() {
+  }
+
+  public static boolean isValidInstallEndpoint(String endpoint) {
+    if (endpoint == null || endpoint.isBlank()) {
+      return false;
+    }
+
+    try {
+      URI uri = new URI(endpoint);
+
+      if (uri.getScheme() == null || uri.getHost() == null) {
+        return false;
+      }
+
+      if (!"http".equalsIgnoreCase(uri.getScheme()) && !"https".equalsIgnoreCase(uri.getScheme())) {
+        return false;
+      }
+
+      String host = uri.getHost().toLowerCase();
+      if ("localhost".equals(host) || host.startsWith("127.") || host.equals("0.0.0.0")) {
+        return false;
+      }
+
+      return true;
+    } catch (URISyntaxException e) {
+      return false;
+    }
+  }
+}
