+      case '>=':
+        return version < required;
+      case '<=':
+        return version > required;
+      case '>':
+        return version <= required;
+      case '<':
+        return version >= required;
+      case '==':
+      case '=':
+        return version !== required;
+      default:
+        return version < required;
